#!/bin/bash
# Million-scale RUNTIME sweep (wall-clock only; no quality metrics reported).
#
# One-factor-at-a-time around a center configuration on synthetic data
# (data/synth_n<N>: n=20 numeric base features, binary classification,
# generated by scripts/efficiency_synth.py, seed 0).
#
# Axes                       values
#   N      (rows)            10k 50k 100k 500k 1M
#   B      (training budget) 128 256 512 1024 2048
#   D_max  (expr. depth)     2 3 4 5 6
#   |O|    (operator vocab)  2 4 6 9
#   k      (final top-k)     8 16 32 64
# Center: N=$CENTER_N, B=256, D=4, |O|=9, k=16; score_mode=mi, lam=1,
# total_iter=3, parallel_eval. Each cell runs in a FRESH pool dir (no cache
# resume) and appends one row to timing.csv; existing rows are skipped.
#
# Usage:
#   PYTHON=... [CENTER_N=1000000] bash scripts/run_million_scale.sh <cuda>

set -o pipefail

cuda=${1:?missing cuda id}
PYTHON=${PYTHON:-python}
CENTER_N=${CENTER_N:-1000000}
export PYTHONIOENCODING=utf-8

C_B=256; C_D=4; C_OPS=""; C_NOPS=9; C_K=16
N_AXIS=(10000 50000 100000 500000 1000000)
B_AXIS=(128 256 512 1024 2048)
D_AXIS=(2 3 4 5 6)
O_LABELS=(2 4 6 9)
O_SETS=("+,*" "+,-,*,division" "+,-,*,division,log,sqrt_abs" "")
K_AXIS=(8 16 32 64)

DIR="outputs_num/scal_million"
mkdir -p "$DIR/cells"
CSV="$DIR/timing.csv"
LOG="$DIR/sweep.log"
[ -f "$CSV" ] || echo "axis,value,N,B,D,nops,k,seconds,exit" > "$CSV"

run_cell() {  # axis value N B D ops nops k
    local axis=$1 value=$2 N=$3 B=$4 D=$5 ops=$6 nops=$7 k=$8
    if grep -q "^${axis},${value}," "$CSV"; then
        echo "[skip] $axis=$value (cached)" | tee -a "$LOG"; return 0
    fi
    local cell="$DIR/cells/${axis}_${value}"
    rm -rf "$cell"; mkdir -p "$cell/pool" "$cell/ckps"
    local EXTRA=()
    [ -n "$ops" ] && EXTRA+=("--ops=$ops")
    echo "===== $axis=$value  (N=$N B=$B D=$D |O|=$nops k=$k) =====" | tee -a "$LOG"
    local t0=$(date +%s)
    PYTHONPATH=. "$PYTHON" autolearn/feat_selection/nfo/iter_train.py \
        --eval_model=RF --data="synth_n${N}" --cuda="$cuda" \
        --hyper_config=default --method=lsbo --total_iter=3 \
        --score_mode=mi --lam=1.0 --random_set_size="$B" \
        --max_order="$D" --select_k="$k" \
        --num_ops_only --parallel_eval "${EXTRA[@]}" \
        --feat_pool="$cell/pool" --ckp_path="$cell/ckps" \
        > "$cell/run.log" 2>&1
    local ec=$?
    local secs=$(( $(date +%s) - t0 ))
    echo "${axis},${value},${N},${B},${D},${nops},${k},${secs},${ec}" >> "$CSV"
    echo "[done] $axis=$value in ${secs}s (exit=$ec)" | tee -a "$LOG"
}

# center (shared reference point for every axis)
run_cell center "$CENTER_N" "$CENTER_N" $C_B $C_D "$C_OPS" $C_NOPS $C_K

for N in "${N_AXIS[@]}"; do
    [ "$N" = "$CENTER_N" ] && continue
    run_cell N "$N" "$N" $C_B $C_D "$C_OPS" $C_NOPS $C_K
done
for B in "${B_AXIS[@]}"; do
    [ "$B" = "$C_B" ] && continue
    run_cell B "$B" "$CENTER_N" "$B" $C_D "$C_OPS" $C_NOPS $C_K
done
for D in "${D_AXIS[@]}"; do
    [ "$D" = "$C_D" ] && continue
    run_cell D "$D" "$CENTER_N" $C_B "$D" "$C_OPS" $C_NOPS $C_K
done
for i in "${!O_LABELS[@]}"; do
    [ "${O_LABELS[$i]}" = "$C_NOPS" ] && continue
    run_cell O "${O_LABELS[$i]}" "$CENTER_N" $C_B $C_D "${O_SETS[$i]}" "${O_LABELS[$i]}" $C_K
done
for k in "${K_AXIS[@]}"; do
    [ "$k" = "$C_K" ] && continue
    run_cell K "$k" "$CENTER_N" $C_B $C_D "$C_OPS" $C_NOPS "$k"
done

echo "MILLION_SCALE_SWEEP_DONE (timing in $CSV)" | tee -a "$LOG"
